var wm=UnityEngine.Object.FindObjectOfType<WaveManager>();var castle=GameObject.FindWithTag("Base").GetComponent<Base>();
UnityEngine.Object.FindObjectOfType<GameManager>().enabled=false;
UnityEngine.AI.NavMesh.SamplePosition(wm.spawnPoint.position,out var start,20,UnityEngine.AI.NavMesh.AllAreas);
UnityEngine.AI.NavMesh.SamplePosition(castle.transform.position,out var end,20,UnityEngine.AI.NavMesh.AllAreas);
var filter=new UnityEngine.AI.NavMeshQueryFilter{agentTypeID=wm.waves[0].groups[0].enemyPrefab.GetComponent<UnityEngine.AI.NavMeshAgent>().agentTypeID,areaMask=UnityEngine.AI.NavMesh.AllAreas};
var path=new UnityEngine.AI.NavMeshPath();bool found=UnityEngine.AI.NavMesh.CalculatePath(wm.spawnPoint.position,castle.transform.position,filter,path);
var points=new System.Collections.Generic.List<Vector3>();
for(int i=1;i<path.corners.Length;i++){float distance=Vector3.Distance(path.corners[i-1],path.corners[i]);for(float d=0;d<distance;d+=.1f)points.Add(Vector3.Lerp(path.corners[i-1],path.corners[i],d/distance));}
return new{found,status=path.status.ToString(),length=points.Count*.1f,slots=UnityEngine.Object.FindObjectsOfType<TowerSlot>().Select(s=>new{s.name,parent=s.transform.parent==null?"":s.transform.parent.name,x=s.transform.position.x,z=s.transform.position.z,archer=points.Count(p=>Vector3.Distance(p,s.transform.position)<=4.7f)*.1f,magic=points.Count(p=>Vector3.Distance(p,s.transform.position)<=3.4f)*.1f,mortar=points.Count(p=>Vector3.Distance(p,s.transform.position)<=4.8f)*.1f}).ToArray(),prefabs=UnityEditor.AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs"}).Select(g=>UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(UnityEditor.AssetDatabase.GUIDToAssetPath(g))).Where(p=>p.GetComponent<Tower>()!=null).Select(p=>new{path=UnityEditor.AssetDatabase.GetAssetPath(p),type=p.GetComponent<Tower>().data.type}).ToArray(),bullets=Resources.LoadAll<BulletData>("Data/BulletData").Select(b=>new{b.name,type=b.bulletType}).ToArray()};
